CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_earned_premium
COMMENT 'Harbour has no earning engine in this extract, so earned premium is derived here on the core convention - daily pro-rata over the period - month by month. Grain: One row per policy period per accounting month with cover in force. Conformed from HARBOUR_PC (lr_serverless_aws_us_catalog.bricksurance_harbour_pc.pc_policyperiod) by mapping harbour_pc; column names and definitions are the core concept premium_earning. Owner Harbour Mutual, Head of Personal Lines; certified.'
AS
WITH months AS (
  SELECT p.PublicID, p.ProductCode, p.TotalPremiumRPT, p.PeriodStart, p.PeriodEnd, m AS month_start
  FROM lr_serverless_aws_us_catalog.bricksurance_harbour_pc.pc_policyperiod p
  LATERAL VIEW explode(sequence(trunc(p.PeriodStart, 'MM'), trunc(p.PeriodEnd, 'MM'), interval 1 month)) AS m
)
SELECT concat('HARBOUR_PC:', PublicID) AS policy_id,
       CAST(TotalPremiumRPT * (datediff(LEAST(date_add(PeriodEnd, 1), add_months(month_start, 1)), GREATEST(PeriodStart, month_start))) / 365.0 AS DECIMAL(18,2)) AS earned_premium,
       year(month_start) * 100 + month(month_start) AS accounting_month,
       concat(year(month_start), 'Q', quarter(month_start)) AS accident_quarter,
       CAST(datediff(LEAST(date_add(PeriodEnd, 1), add_months(month_start, 1)), GREATEST(PeriodStart, month_start)) AS DECIMAL(18,6)) / 365.0 AS vehicle_years,
       CASE ProductCode WHEN 'PersonalAuto' THEN 'HP' ELSE 'HC' END AS motor_segment_code
FROM months
WHERE datediff(LEAST(date_add(PeriodEnd, 1), add_months(month_start, 1)), GREATEST(PeriodStart, month_start)) > 0;

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_earned_premium.policy_id IS 'Stable, source-agnostic identifier for the policy.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_earned_premium.earned_premium IS 'Premium earned in the month, GBP, daily pro-rata over the policy period.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_earned_premium.accounting_month IS 'Accounting month as YYYYMM.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_earned_premium.accident_quarter IS 'Calendar quarter of the accounting month, e.g. 2026Q3.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_earned_premium.vehicle_years IS 'Policy-years of exposure in the month (one vehicle assumed per personal policy; commercial fleets count their vehicles via pc_vehicle).';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_harbour_earned_premium.motor_segment_code IS 'HP personal auto, HC commercial auto.';

